export function getVerifiedPlatform(key: string) {
  const data = VERIFIED_PLATFORM_DATA[key];
  if (!data) return undefined;
  return { ...data, pins: data.pins.map(([name, signal, pin, type, group, activeLow, ioStandard, verified]): BoardPin => ({ name, signal, pin, type, group, ...(activeLow === null ? {} : { activeLow }), ...(ioStandard === null ? {} : { ioStandard }), verified })) };
}
